def _calculate_minhash_fingerprint(
    self, mol: Mol, a: np.ndarray, b: np.ndarray
) -> np.ndarray:
    shingles = self._get_shingles(mol)
    if not shingles:
        return np.full(self.fp_size, MAX_HASH, dtype=np.uint32)

    hash_values = np.array(
        [
            struct.unpack("<I", sha256(shingle).digest()[:4])[0]
            for shingle in shingles
        ],
        dtype=np.uint64,
    )
    # MinHash: for each permutation, keep the minimum hashed shingle value
    permuted = (hash_values[:, None] * a + b) % MERSENNE_PRIME
    return permuted.min(axis=0).astype(np.uint32)

def _get_minhash_permutations(self) -> tuple[np.ndarray, np.ndarray]:
    from sklearn.utils import check_random_state

    rng = check_random_state(self.random_state)
    a = rng.randint(1, MERSENNE_PRIME, size=self.fp_size, dtype=np.uint64)
    b = rng.randint(0, MERSENNE_PRIME, size=self.fp_size, dtype=np.uint64)
    return a, b

def _get_atom_envs(self, mol: Mol) -> dict[int, list[str | None]]:
    from rdkit.Chem import FindMolChiralCenters

    # build the atom environment labels for each radius.
    atom_envs: dict[int, list[str | None]] = defaultdict(list)

    for atom in mol.GetAtoms():
        atom_idx = atom.GetIdx()
        for radius in range(1, self.radius + 1):
            atom_env = self._find_env(mol, atom_idx, radius)
            atom_envs[atom_idx].append(atom_env)

    if self.include_chirality:
        chiral_centers = FindMolChiralCenters(mol, includeUnassigned=True)
        for atom_idx, cip_label in chiral_centers:
            max_radius_smiles = atom_envs[atom_idx][-1]
            if max_radius_smiles:
                atom_envs[atom_idx][-1] = self._replace_first_atom_symbol(
                    max_radius_smiles, f"${cip_label}$"
                )
